<?php
/* TEMPORARY (owner, 13 Nov 2026): Art Education: a new free-licence cover painting for each of the 5 guides, with its credit
   line, and the spelling fixes (colours → colors). Makes a full backup first. The publish status is NOT changed.
   Locked by a secret key, runs once. Removed straight after. */
if (!hash_equals('9b3bce25d46251534b3f4937ec9cbf39eab90507715d3af0235f5c6f4e619df2', hash('sha256', (string) ($_GET['k'] ?? '')))) { http_response_code(404); exit; }
require_once __DIR__ . '/config.php';
header('Content-Type: text/plain; charset=utf-8'); header('Cache-Control: no-store'); header('X-Robots-Tag: noindex');
@set_time_limit(300);
$db = getDB();
$plan = json_decode(base64_decode(''), true);
$show = function () use ($db) { foreach ($db->query("SELECT id, slug, status, cover_image_path FROM articles WHERE type = 'art_education' ORDER BY id") as $r) echo $r['id'], ' | ', $r['status'], ' | ', $r['slug'], ' | ', $r['cover_image_path'], "\n"; };
if (($_GET['a'] ?? '') !== 'run') { $show(); foreach ($plan as $p) echo 'file ', $p['img'], ': ', is_file(__DIR__ . '/' . $p['img']) ? 'ok' : 'MISSING', "\n"; exit; }
if (is_file(__DIR__ . '/.logs/zz-edu-done')) { echo "already run\n"; $show(); exit; }
$dbName = (string) $db->query('SELECT DATABASE()')->fetchColumn();
/* 1. full backup */
$dir = __DIR__ . '/.backups';
if (!is_dir($dir)) { @mkdir($dir, 0700, true); }
if (!is_file($dir . '/.htaccess')) { @file_put_contents($dir . '/.htaccess', "Require all denied\n"); }
$file = $dir . '/db-' . preg_replace('/[^a-z0-9_]/i', '', $dbName) . '-' . gmdate('Ymd-His') . '.sql.gz';
$gz = gzopen($file, 'wb6');
if (!$gz) { echo "backup FAILED: cannot write\n"; exit; }
gzwrite($gz, "-- Oweili full backup " . gmdate('c') . "\nSET NAMES utf8mb4;\nSET FOREIGN_KEY_CHECKS=0;\n");
$tables = $db->query('SHOW FULL TABLES WHERE Table_type = "BASE TABLE"')->fetchAll(PDO::FETCH_COLUMN);
$rows = 0;
foreach ($tables as $t) {
    $t = str_replace('`', '', (string) $t);
    $c = $db->query("SHOW CREATE TABLE `$t`")->fetch(PDO::FETCH_NUM);
    gzwrite($gz, "\nDROP TABLE IF EXISTS `$t`;\n" . $c[1] . ";\n");
    $st = $db->query("SELECT * FROM `$t`");
    while ($r = $st->fetch(PDO::FETCH_NUM)) {
        $vals = array_map(fn($v) => $v === null ? 'NULL' : $db->quote((string) $v), $r);
        gzwrite($gz, "INSERT INTO `$t` VALUES (" . implode(',', $vals) . ");\n");
        $rows++;
    }
}
gzwrite($gz, "\nSET FOREIGN_KEY_CHECKS=1;\n");
gzclose($gz);
$size = (int) filesize($file);
if ($size < 500) { echo "backup FAILED (too small)\n"; exit; }
echo "backup ok: .backups/" . basename($file) . " (" . count($tables) . " tables, $rows rows, $size bytes)\n";
$dir = __DIR__ . '/uploads/articles';
if (!is_dir($dir)) @mkdir($dir, 0755, true);
$st = $db->prepare("UPDATE articles SET cover_image_path = :c, body_en = :be, body_ar = :ba WHERE id = :id AND slug = :s AND type = 'art_education'");
$n = 0;
foreach ($plan as $p) {
    $src = __DIR__ . '/' . $p['img'];
    if (!is_file($src)) { echo "skip (no file) ", $p['id'], "\n"; continue; }
    $name = bin2hex(random_bytes(16)) . '.jpg';
    if (!@copy($src, $dir . '/' . $name)) { echo "skip (copy failed) ", $p['id'], "\n"; continue; }
    $st->execute([':c' => 'uploads/articles/' . $name, ':be' => $p['body_en'], ':ba' => $p['body_ar'], ':id' => (int) $p['id'], ':s' => $p['slug']]);
    $n += $st->rowCount();
}
@file_put_contents(__DIR__ . '/.logs/zz-edu-done', gmdate('c'));
echo "updated: $n\n"; $show();
